import{_ as s,o as n,c as e,ai as p}from"./chunks/framework.ampVZV4B.js";const o=JSON.parse('{"title":"AI × 工业：MES 里真正值得先做什么","description":"","frontmatter":{},"headers":[],"relativePath":"ai/app/manufacturing/mes-assistant.md","filePath":"ai/app/manufacturing/mes-assistant.md"}'),i={name:"ai/app/manufacturing/mes-assistant.md"};function l(r,a,t,c,h,b){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="ai-×-工业-mes-里真正值得先做什么" tabindex="-1">AI × 工业：MES 里真正值得先做什么 <a class="header-anchor" href="#ai-×-工业-mes-里真正值得先做什么" aria-label="Permalink to “AI × 工业：MES 里真正值得先做什么”">​</a></h1><p>原文就一句话：设备异常解释、点检、工单知识问答——<strong>先辅助人，再谈自动控制。</strong> 下面把这句话说清楚：工业里 AI 该从哪切，以及为什么不要急着替代生产系统。</p><p>这不是工业 AI 场景大全，也不是「我已经做过 AI MES」的项目报告。</p><hr><h2 id="为什么工业里的-ai-要更克制" tabindex="-1">为什么工业里的 AI 要更克制 <a class="header-anchor" href="#为什么工业里的-ai-要更克制" aria-label="Permalink to “为什么工业里的 AI 要更克制”">​</a></h2><p>MES / 工控相关系统和普通互联网后台不一样：对着真实生产，数据、权限、状态、规则都更硬。一条错建议可能影响排产、质量和安全。现场很多事规则已经写死——能用规则算准的，不必硬上模型。</p><p>AI 更适合：信息量大、来源杂、人要读要判、规则写不完、而且可以复核。生产执行本身，先留给原来的系统。</p><hr><h2 id="mes-里我更愿意先看的切口" tabindex="-1">MES 里我更愿意先看的切口 <a class="header-anchor" href="#mes-里我更愿意先看的切口" aria-label="Permalink to “MES 里我更愿意先看的切口”">​</a></h2><p>不堆十几个场景。结合常见 MES / 车间系统，我先看这几类。</p><h3 id="_1-生产异常辅助分析" tabindex="-1">1. 生产异常辅助分析 <a class="header-anchor" href="#_1-生产异常辅助分析" aria-label="Permalink to “1. 生产异常辅助分析”">​</a></h3><p>设备、工单、质量出异常之后，让 AI 帮着整理：发生了什么、牵涉哪些工单/设备/产品、近期相关记录、可能原因、建议再查什么。</p><p>它给出的是分析和建议，<strong>不替代现场的最终判断</strong>。人确认后，该停线停线、该开维修工单开维修工单，仍走原流程。</p><h3 id="_2-生产-业务数据问答" tabindex="-1">2. 生产 / 业务数据问答 <a class="header-anchor" href="#_2-生产-业务数据问答" aria-label="Permalink to “2. 生产 / 业务数据问答”">​</a></h3><p>例如：今天哪些工单延期、哪台设备最近告警多、某产品这周生产情况如何。价值不在「聊天」，而在少翻几个页面、少拼几张报表。</p><p>真正难的是权限、口径、查询安全、上下文、结果能不能对账。接一个对话 API 不算做完。答出来的数，最好能回到原报表或原查询去核对。</p><h3 id="_3-工艺-设备-维修知识辅助" tabindex="-1">3. 工艺 / 设备 / 维修知识辅助 <a class="header-anchor" href="#_3-工艺-设备-维修知识辅助" aria-label="Permalink to “3. 工艺 / 设备 / 维修知识辅助”">​</a></h3><p>现场通常不缺文档：SOP、工艺、说明书、维修记录、故障经验、培训材料。缺的是用的时候找得到、对得上当前设备与工序。</p><p>这里会用到企业知识库一类做法，但重点不是 RAG 教程，而是：<strong>让已有知识更好用，而不是再造一套知识。</strong> 答不上来就说不确定，并指出该翻哪份资料。</p><h3 id="_4-日报-周报-异常报告草稿" tabindex="-1">4. 日报 / 周报 / 异常报告草稿 <a class="header-anchor" href="#_4-日报-周报-异常报告草稿" aria-label="Permalink to “4. 日报 / 周报 / 异常报告草稿”">​</a></h3><p>把分散的产量、异常、设备、工单进度、质量记录收成一稿，人改完再发。生成草稿可以快；签字和对外口径仍是人的事。</p><h3 id="_5-质检与异常信息整理" tabindex="-1">5. 质检与异常信息整理 <a class="header-anchor" href="#_5-质检与异常信息整理" aria-label="Permalink to “5. 质检与异常信息整理”">​</a></h3><p>缺陷描述归类、异常记录归纳、质检摘要、查历史上类似问题——仍然是减阅读、助检索。不是「视觉自动质检已经落地」。视觉检测是另一条更重的路线，本文不展开。</p><p>点检助手也可以落在「对着规程和最近记录，提醒漏项、解释异常」，同样是辅助，不是自动改点检结论。</p><hr><h2 id="哪些地方暂时不要让-ai-接管" tabindex="-1">哪些地方暂时不要让 AI 接管 <a class="header-anchor" href="#哪些地方暂时不要让-ai-接管" aria-label="Permalink to “哪些地方暂时不要让 AI 接管”">​</a></h2><ul><li>不要急着让 AI 做最终生产决策（开不停、改不改工艺、放不放行）。</li><li>不要让它绕过原有权限：能看哪些工单、能下哪类指令，仍以 MES 为准。</li><li>不要让它直接改核心生产数据（计划、报工、库存、工艺参数）。</li><li>不要用它替代已经明确的业务规则（批次、防错、互锁）。</li><li>不要因为有了大模型，就重做整套 MES。</li></ul><blockquote><p><strong>AI 是能力层，不该轻易破坏原系统的确定性。</strong></p></blockquote><hr><h2 id="ai-和-mes-是什么关系" tabindex="-1">AI 和 MES 是什么关系 <a class="header-anchor" href="#ai-和-mes-是什么关系" aria-label="Permalink to “AI 和 MES 是什么关系”">​</a></h2><p>更接近现实的形状：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MES / ERP / IoT</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>业务数据与业务上下文</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>AI 能力</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>分析 / 总结 / 检索 / 建议</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>人工确认</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>原有业务系统执行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>MES 更擅长：数据、状态、规则、流程、权限、事务。<br> AI 更擅长：读文本、整理信息、检索知识、归纳模式、自然语言入口、辅助分析。</p><p>两者不是互相替换。更稳的做法是：<strong>让 AI 站在传统业务系统旁边，而不是一上来替代它。</strong></p><p>我做企业系统时间比较长，所以看 AI + MES，不会先问「能不能做一个车间 Agent」。我更关心三件事：这个环节原来的人到底耗在读和查上多久；AI 能不能真减信息处理成本；出错以后能不能被发现、被拦住。三个问题答不上来，多半只是多了一个聊天窗口。</p><p>工业里真正有用的 AI，不一定最「聪明」，往往是最容易嵌进现有流程、结果最好核对的那一个。</p><hr><h2 id="一个简单判断" tabindex="-1">一个简单判断 <a class="header-anchor" href="#一个简单判断" aria-label="Permalink to “一个简单判断”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>高频信息处理</span></span>
<span class="line"><span>  + 已有业务数据</span></span>
<span class="line"><span>  + AI 能明显减轻阅读/查找</span></span>
<span class="line"><span>  + 允许人工复核</span></span>
<span class="line"><span>  + 能嵌进原有 MES 流程</span></span>
<span class="line"><span>  → 值得试</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高风险 + 无法复核 + 数据很差 + 规则已经写死</span></span>
<span class="line"><span>  → 先不上</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h2 id="收束" tabindex="-1">收束 <a class="header-anchor" href="#收束" aria-label="Permalink to “收束”">​</a></h2><p>对我来说，AI + 工业不是把一个大模型塞进 MES。更现实的是先钉死一个信息处理环节，让人把事做快一点，再慢慢进更重的流程。</p><p><strong>先辅助人，再进入流程；先解决具体问题，再谈智能化。</strong></p><p>本文是基于企业软件、MES / 业务系统经验的方向判断，<strong>不代表已经完成上述工业 AI 项目的落地</strong>。不虚构客户、准确率或收益。以后若在具体模块上做了验证，再单独写结果。</p>`,44)])])}const m=s(i,[["render",l]]);export{o as __pageData,m as default};
